alter table public.provider_compliance_evidence_links add constraint provider_compliance_evidence_links_org_id_unique unique (organization_id,id);
alter table public.provider_compliance_evidence_links add constraint provider_compliance_evidence_links_org_fkey foreign key (organization_id) references public.organizations(id) on delete restrict;
alter table public.provider_compliance_evidence_links add constraint provider_compliance_evidence_links_evaluation_fkey foreign key (organization_id,evaluation_id,provider_relationship_id,legal_entity_id) references public.provider_compliance_evaluations(organization_id,id,provider_relationship_id,legal_entity_id) on delete cascade;
alter table public.provider_compliance_evidence_links add constraint provider_compliance_evidence_links_result_fkey foreign key (organization_id,rule_result_id) references public.provider_compliance_rule_results(organization_id,id) on delete restrict;
alter table public.provider_compliance_evidence_links add constraint provider_compliance_evidence_links_document_fkey foreign key (organization_id,document_version_id,provider_relationship_id,legal_entity_id) references public.provider_document_versions(organization_id,id,provider_relationship_id,legal_entity_id) on delete restrict;
